/// Procedural fixture images for the M01 render spike (T-02 FIX-01, FIX-04).
///
/// Generated by this code, owned by the project, no third-party content and
/// no real people. Deterministic: the same call yields the same pixels on
/// every platform, so device renders can be compared with host goldens.
library;

import 'dart:math' as math;
import 'dart:typed_data';

/// An opaque sRGB colour.
final class Rgb {
  const Rgb(this.r, this.g, this.b);

  final int r;
  final int g;
  final int b;

  /// This colour drawn at [alpha] (0..1) over [background].
  Rgb over(Rgb background, double alpha) => Rgb(
    (r * alpha + background.r * (1 - alpha)).round(),
    (g * alpha + background.g * (1 - alpha)).round(),
    (b * alpha + background.b * (1 - alpha)).round(),
  );

  int get argb => 0xFF000000 | (r << 16) | (g << 8) | b;

  @override
  bool operator ==(Object other) =>
      other is Rgb && other.r == r && other.g == g && other.b == b;

  @override
  int get hashCode => Object.hash(r, g, b);

  @override
  String toString() => 'rgb($r, $g, $b)';
}

/// Straight-alpha RGBA pixels with their size.
final class RgbaImage {
  RgbaImage(this.width, this.height) : pixels = Uint8List(width * height * 4);

  final int width;
  final int height;
  final Uint8List pixels;

  void set(int x, int y, Rgb colour, double alpha) {
    final i = (y * width + x) * 4;
    pixels
      ..[i] = colour.r
      ..[i + 1] = colour.g
      ..[i + 2] = colour.b
      ..[i + 3] = (alpha.clamp(0, 1) * 255).round();
  }
}

/// Opaque stripes [stripePx] wide, alternating [even] and [odd] colours;
/// vertical stripes vary along x, horizontal ones along y.
RgbaImage stripes({
  required int width,
  required int height,
  required int stripePx,
  required bool vertical,
  required Rgb even,
  required Rgb odd,
}) {
  final image = RgbaImage(width, height);
  for (var y = 0; y < height; y++) {
    for (var x = 0; x < width; x++) {
      final index = (vertical ? x : y) ~/ stripePx;
      image.set(x, y, index.isEven ? even : odd, 1);
    }
  }
  return image;
}

/// Anti-aliased coverage of a pixel whose centre is [distance] px inside (+)
/// or outside (-) a shape edge.
double _coverage(double distance) => (distance + 0.5).clamp(0, 1).toDouble();

/// A stylised flower on a transparent background: six translucent petals
/// (alpha [petalAlpha]) under an opaque centre disc, all edges anti-aliased.
///
/// Geometry, as fractions of [size]: disc radius 0.15; petal ellipses with
/// semi-axes 0.2125 (radial) and 0.11875 centred 0.275 from the centre at
/// 0°, 60°, ... 300° (0° points right, angles turn clockwise).
RgbaImage flower({
  required int size,
  Rgb disc = const Rgb(232, 180, 60),
  Rgb petal = const Rgb(236, 120, 150),
  double petalAlpha = 0.75,
}) {
  final image = RgbaImage(size, size);
  final c = size / 2;
  final discRadius = 0.15 * size;
  final petalOffset = 0.275 * size;
  final radialAxis = 0.2125 * size;
  final tangentialAxis = 0.11875 * size;
  for (var y = 0; y < size; y++) {
    for (var x = 0; x < size; x++) {
      final px = x + 0.5 - c;
      final py = y + 0.5 - c;
      final discCover = _coverage(discRadius - math.sqrt(px * px + py * py));
      var petalCover = 0.0;
      for (var k = 0; k < 6; k++) {
        final angle = k * math.pi / 3;
        final dx = px - petalOffset * math.cos(angle);
        final dy = py - petalOffset * math.sin(angle);
        // Rotate into the petal's frame (radial axis along +x).
        final u = dx * math.cos(angle) + dy * math.sin(angle);
        final v = -dx * math.sin(angle) + dy * math.cos(angle);
        final normalised = math.sqrt(
          (u / radialAxis) * (u / radialAxis) +
              (v / tangentialAxis) * (v / tangentialAxis),
        );
        final distance = (1 - normalised) * tangentialAxis;
        petalCover = math.max(petalCover, _coverage(distance));
      }
      final petalA = petalCover * petalAlpha;
      final alpha = discCover + petalA * (1 - discCover);
      if (alpha <= 0) continue; // fully transparent (0, 0, 0, 0)
      final mix = discCover / alpha;
      image.set(
        x,
        y,
        Rgb(
          (disc.r * mix + petal.r * (1 - mix)).round(),
          (disc.g * mix + petal.g * (1 - mix)).round(),
          (disc.b * mix + petal.b * (1 - mix)).round(),
        ),
        alpha,
      );
    }
  }
  return image;
}

/// An opaque bar: left half [left], right half [right]. Shows rotation
/// direction and pivot unambiguously.
RgbaImage marker({
  required int width,
  required int height,
  Rgb left = const Rgb(220, 30, 30),
  Rgb right = const Rgb(30, 30, 220),
}) {
  final image = RgbaImage(width, height);
  for (var y = 0; y < height; y++) {
    for (var x = 0; x < width; x++) {
      image.set(x, y, x < width ~/ 2 ? left : right, 1);
    }
  }
  return image;
}

/// FIX-04 halo probe: an anti-aliased [colour] disc whose fully transparent
/// pixels carry [transparentRgb]. Filtering in premultiplied alpha ignores
/// that hidden colour; a pipeline that filters straight alpha bleeds it into
/// the disc edge as a dark or light halo.
RgbaImage haloDisc({
  required int size,
  required Rgb colour,
  required Rgb transparentRgb,
}) {
  final image = RgbaImage(size, size);
  final c = size / 2;
  final radius = 0.4 * size;
  for (var y = 0; y < size; y++) {
    for (var x = 0; x < size; x++) {
      final px = x + 0.5 - c;
      final py = y + 0.5 - c;
      final cover = _coverage(radius - math.sqrt(px * px + py * py));
      image.set(x, y, cover > 0 ? colour : transparentRgb, cover);
    }
  }
  return image;
}
